s=s.replace("$('#vt').textContent=T.visit;","ID('w_cap').textContent=T.web.cap;setChips('w_chips',T.web.chips,0);ID('w_tick').textContent=T.web.tick;ID('s_cap').textContent=T.soft.cap;setChips('s_chips',T.soft.chips,1);ID('s_inv').textContent=T.soft.inv;ID('d_cap').textContent=T.des.cap;ID('v_cap').textContent=T.vid.cap;setChips('v_chips',T.vid.chips,1);ID('h_t').textContent=T.how.title;T.how.steps.forEach((x,i)=>ID('h_l'+i).textContent=x);ID('wt').textContent=T.wall.t;ID('ws').textContent=T.wall.s;$('#vt').textContent=T.visit;",1)
code=r'''
 const Tt=T;
 const trans=(el,sl,dur,inT=.45,outT=.4)=>{const a=eo(sl/inT),b=eio((sl-(dur-outT))/outT);el.style.opacity=a*(1-b);el.style.filter=`blur(${(1-a)*14+b*14}px)`;el.style.transform=`translateX(${(1-a)*90-b*90}px)`};
 if(['web','soft','des','vid','how','wall','more','visit'].includes(key))trans(SC[key],sl,dur);else{SC[key].style.opacity=1;SC[key].style.filter='none';SC[key].style.transform='none'}
 if(key==='hook'){const p=clamp((sl-.4)/10),path=ID('hk_p'),L=path.getTotalLength(),pt=path.getPointAtLength(L*p),pt2=path.getPointAtLength(Math.min(L,L*p+10));ID('hk_r').setAttribute('width',pt.x);ID('hk_pl').setAttribute('transform',`translate(${pt.x} ${pt.y}) rotate(${Math.atan2(pt2.y-pt.y,pt2.x-pt.x)*180/Math.PI+90})`);ID('hk_pl').style.opacity=p>0?1:0}
 if(key==='web'){ID('w_cap').style.opacity=eo((sl-.2)/.6);ID('w_cap').style.transform=`translateX(${(1-eo((sl-.2)/.6))*-60}px)`;const w=ID('w_win');const wi=bk(sl/.8),wo=eio((sl-(dur-.9))/.6);w.style.transform=`translateY(${(1-clamp(wi))*600+wo*700}px)`;const u='yourshop.in';ID('w_url').textContent=u.slice(0,Math.floor(clamp((sl-.9)/1.2)*u.length));const pop=(id,d)=>{const e=ID(id),p=bk((sl-d)/.4);e.style.opacity=clamp(p);e.style.transform=`scale(${.7+.3*clamp(p)})`};pop('w_hero',2.2);document.querySelectorAll('.w_c').forEach((e,i)=>{const p=bk((sl-2.6-i*.3)/.4);e.style.opacity=clamp(p);e.style.transform=`translateY(${(1-clamp(p))*30}px)`});pop('w_btn',3.6);
  const cp=eio((sl-4.2)/1.0);const cx=1700+(1104-1700)*cp,cy=860+(723-860)*cp;ID('w_cur').style.transform=`translate(${cx}px,${cy}px)`;ID('w_cur').style.opacity=sl>4.0?1:0;const pr=clamp((sl-5.3)/.15)*(1-clamp((sl-5.5)/.2));ID('w_btn').style.transform=`scale(${1-.08*pr})`;ID('w_btn').style.background=sl>5.4?'#3DBE8B':'#FDB022';ID('w_tick').style.opacity=eo((sl-5.7)/.4);ID('w_tick').style.transform=`translateY(${(1-eo((sl-5.7)/.4))*30}px)`;typeChips('w_chips',sl,2.4,.3)}
 if(key==='soft'){ID('s_cap').style.opacity=eo((sl-.2)/.6);ID('s_cap').style.transform=`translateX(${(1-eo((sl-.2)/.6))*-60}px)`;const w=ID('s_win');const wi=bk(sl/.8),wo=eio((sl-(dur-.9))/.6);w.style.transform=`translateY(${(1-clamp(wi))*700+wo*800}px)`;document.querySelectorAll('.s_r').forEach((r,i)=>{const p=bk((sl-1.0-i*.6)/.5);r.style.opacity=clamp(p);r.style.transform=`translateY(${(1-clamp(p))*-120}px)`;const ok=r.querySelector('.s_ok');ok.style.opacity=sl>1.8+i*.6?1:0;ok.style.display='inline-block';ok.style.transform=`scale(${.6+.4*bk((sl-1.8-i*.6)/.3)})`});const iv=ID('s_inv'),ip=bk((sl-4.0)/.6);iv.style.opacity=clamp(ip);iv.style.transform=`translateY(${(1-clamp(ip))*120}px)`;typeChips('s_chips',sl,3.6,.35)}
 if(key==='des'){ID('d_cap').style.opacity=eo(sl/.6);const sw=[eio((sl-3.0)/.6),eio((sl-6.2)/.6)];const pos=sw[0]+sw[1];ID('d_wrap').style.transform=`translateX(${-pos*1920}px)`;const mv=Math.min(1,Math.abs(sw[0]*(1-sw[0]))*4+Math.abs(sw[1]*(1-sw[1]))*4);ID('d_wrap').style.filter=`blur(${mv*10}px)`;const si=pos<.5?0:pos<1.5?1:2;const st=[0,3.6,6.8][si];const txt=Tt.des.ban[si];ID('d_ban').textContent=txt.slice(0,Math.floor(clamp((sl-st-.2)/.7)*txt.length));ID('d_ban').style.opacity=clamp((sl-st+.1)/.2);document.querySelectorAll('#d_dots i').forEach((d,i)=>d.style.background=i===si?'#111':'#1114')}
 if(key==='vid'){ID('v_cap').style.opacity=eo((sl-.2)/.6);ID('v_cap').style.transform=`translateX(${(1-eo((sl-.2)/.6))*-60}px)`;const ph=ID('v_ph'),pi=bk(sl/.7);const tl=ID('v_tl'),ti=bk((sl-.3)/.7);const out=eio((sl-(dur-.6))/.5);ph.style.transform=`translateY(${(1-clamp(pi))*-700-out*700}px)`;tl.style.transform=`translateY(${(1-clamp(ti))*400+out*400}px)`;const p=clamp((sl-1.0)/6.8);ID('v_head').style.left=(14+p*1660)+'px';const seg=Math.min(3,Math.floor(p*4)),fi=Math.min(40,1+Math.floor((p*4-seg)*40));document.querySelectorAll('.vf').forEach(f=>f.style.display=(+f.dataset.c===seg&&+f.dataset.i===fi)?'block':'none');typeChips('v_chips',sl,2.2,.4)}
 if(key==='how'){ID('h_t').style.opacity=eo(sl/.6);ID('h_line').style.transform=`scaleX(${eio((sl-.8)/3.2)})`;[0,1,2].forEach(i=>{const st=.6+i*1.5,p=bk((sl-st)/.5);const c=ID('h_c'+i);c.style.opacity=clamp(p);c.style.transform=`scale(${clamp(p)})`;const done=(i<2&&sl>st+1.6)||(i==2&&sl>4.6);c.textContent=done?'✓':String(i+1);c.style.background=done?'#3DBE8B':'#0A2A5E';const l=ID('h_l'+i);l.style.opacity=eo((sl-st-.2)/.5);l.style.transform=`translateY(${(1-eo((sl-st-.2)/.5))*30}px)`})}
 if(key==='wall'){const p=eio((sl-2.5)/6.5);const sc=Math.pow(15,1-p);ID('wg').style.transform=`scale(${sc}) translate(${Math.sin(sl*.4)*4*p}px,${Math.cos(sl*.3)*3*p}px)`;ID('wh').style.transform=`scale(${sc/15})`;const fi=1+Math.floor(sl*10)%40;document.querySelectorAll('.hf').forEach(f=>f.style.display=(+f.dataset.i===fi)?'block':'none');const lg=eo((sl-9.0)/.8);ID('wlogo').style.opacity=lg;ID('wlogo').style.transform=`scale(${.8+.2*lg})`;ID('wt').style.opacity=eo((sl-9.3)/.5);ID('ws').style.opacity=eo((sl-9.9)/.5)}
'''
assert " // text colour in dark rooms\n point(zone,pp);" in s
s=s.replace(" // text colour in dark rooms\n point(zone,pp);",code+" point(zone,pp);",1)
s=s.replace("window.ready=document.fonts.ready.then(()=>new Promise(r=>setTimeout(r,300)));","window.ready=document.fonts.ready.then(()=>waitImgs()).then(()=>new Promise(r=>setTimeout(r,400)));",1)
