old2="nm.style.opacity=eo(clamp((sl-.1)/.5));nm.style.transform=`translateX(${(1-eo(clamp((sl-.1)/.5)))*-40}px)`;"
assert old2 in s
s=s.replace(old2,"const full=T.n[key];nm.textContent=full.slice(0,Math.floor(clamp((sl-.5)/.6)*full.length));nm.style.opacity=clamp((sl-.4)/.2)*(1-ex);",1)
open('loop.html','w').write(s);print('patched')
